from datetime import date, timedelta

def _count_business_days(start_date: date, end_date: date) -> int:
    """Count weekdays (Monday-Friday) from start_date (inclusive) to end_date (exclusive)."""
    if start_date >= end_date:
        return 0

    total_days = (end_date - start_date).days
    start_weekday = start_date.weekday() # Monday is 0, Sunday is 6

    full_weeks, extra_days = divmod(total_days, 7)
    business_days_count = full_weeks * 5

    for i in range(extra_days):
        current_weekday = (start_weekday + i) % 7
        if current_weekday < 5:  # Monday to Friday
            business_days_count += 1

    return business_days_count

def business_days(start: str, end: str) -> int:
    start_date = date.fromisoformat(start)
    end_date = date.fromisoformat(end)

    if start_date <= end_date:
        return _count_business_days(start_date, end_date)
    else:
        return -_count_business_days(end_date, start_date)
